// src/components/Header.js
import React from 'react';
import { Link } from 'react-router-dom';  // Import Link from React Router

function Header() {
  return (
    <header>
      <div className="logo">
        <a href="#"><img src="images/logo.jpg" alt="logo" /></a>
      </div>
      <nav className="nav-menu">
        <ul>
          <li><Link to="/">Home</Link></li>  {/* Link for Home */}
          <li><Link to="/about">About</Link></li>  {/* Link for About */}
          <li><Link to="/destinations">Destinations</Link></li>  {/* Link for Destinations */}
          <li><Link to="/hotels">Hotels</Link></li>  {/* Link for Hotels */}
          <li><Link to="/activities">Activities</Link></li>  {/* Link for Activities */}
          <li><Link to="/contact">Contact</Link></li>  {/* Link for Contact */}
        </ul>
      </nav>
    </header>
  );
}

export default Header;
